//! `chronofork experiment`: produce the canonical experiment artifact.
//!
//! The artifact is generated by the service `experiment.run` operation on the synthetic
//! test backend; the CLI selects a destination and prints or atomically writes the exact
//! canonical document.

use std::error::Error;
use std::fs::File;
use std::io::{self, Write};
use std::path::{Path, PathBuf};

use chronofork_service::ServiceLimits;
use chronofork_service::json::{JsonValue, to_canonical_bytes};

use super::{dispatch_local, json_unsigned, local_service, result_of, write_canonical_line};
use crate::{CliError, VERSION, ensure, option_value, parse_u32, parse_u64, set_once};

/// Runs `chronofork experiment`.
pub(crate) fn run(args: &[String]) -> Result<(), Box<dyn Error>> {
    match args.first().map(String::as_str) {
        None => Err(CliError("`experiment` requires a subcommand: run".to_owned()).into()),
        Some("--help" | "-h") => {
            ensure(
                args.len() == 1,
                "`experiment --help` takes no other arguments",
            )?;
            print_experiment_help();
            Ok(())
        }
        Some("run") => run_experiment_run(&args[1..]),
        Some(other) => Err(CliError(format!(
            "unknown `experiment` subcommand `{other}`; expected run"
        ))
        .into()),
    }
}

/// Parsed `experiment run` flags.
#[derive(Debug, Default)]
struct ExperimentOptions {
    steps: Option<u64>,
    buttons: Option<u32>,
    checkpoints: Option<Vec<u64>>,
    out: Option<PathBuf>,
}

fn run_experiment_run(args: &[String]) -> Result<(), Box<dyn Error>> {
    let Some(options) = parse_experiment_options(args)? else {
        print_experiment_help();
        return Ok(());
    };
    let steps = options
        .steps
        .ok_or_else(|| CliError("`experiment run` requires `--steps <N>`".to_owned()))?;

    let mut members = vec![
        ("steps", json_unsigned(steps, "--steps")?),
        (
            "buttons",
            JsonValue::int(i64::from(options.buttons.unwrap_or(0))),
        ),
    ];
    if let Some(checkpoints) = options.checkpoints {
        let values = checkpoints
            .into_iter()
            .map(|checkpoint| json_unsigned(checkpoint, "--checkpoints"))
            .collect::<Result<Vec<_>, _>>()?;
        members.push(("checkpoints", JsonValue::Array(values)));
    }
    let input = JsonValue::object(members);

    // The artifact is produced by the service; the CLI only selects a backend factory
    // (the synthetic one, the documented default for this command) and a destination.
    let service = local_service(None, None)?;
    let envelope = dispatch_local(&service, "experiment.run", &input)?;
    let result = result_of(&envelope)?;
    let artifact = result
        .get("artifact")
        .ok_or_else(|| CliError("`experiment.run` envelope has no artifact".to_owned()))?;
    let limits = ServiceLimits::default();
    let bytes = to_canonical_bytes(artifact, &limits)?;

    match options.out {
        Some(path) => write_atomic(&path, &bytes)?,
        None => write_canonical_line(&bytes)?,
    }
    Ok(())
}

/// Parses `experiment run` arguments, returning `Ok(None)` when help was requested.
fn parse_experiment_options(args: &[String]) -> Result<Option<ExperimentOptions>, Box<dyn Error>> {
    if args.iter().any(|arg| arg == "--help" || arg == "-h") {
        ensure(
            args.len() == 1,
            "`experiment run --help` takes no other arguments",
        )?;
        return Ok(None);
    }
    let mut options = ExperimentOptions::default();
    let mut index = 0;
    while index < args.len() {
        let flag = args[index].clone();
        match flag.as_str() {
            "--steps" => set_once(
                &mut options.steps,
                parse_u64(option_value(args, &mut index, &flag)?, &flag)?,
                &flag,
            )?,
            "--buttons" => set_once(
                &mut options.buttons,
                parse_u32(option_value(args, &mut index, &flag)?, &flag)?,
                &flag,
            )?,
            "--checkpoints" => {
                let value = option_value(args, &mut index, &flag)?;
                set_once(
                    &mut options.checkpoints,
                    parse_checkpoints(value, &flag)?,
                    &flag,
                )?;
            }
            "--out" => set_once(
                &mut options.out,
                PathBuf::from(option_value(args, &mut index, &flag)?),
                &flag,
            )?,
            other => {
                return Err(CliError(format!(
                    "unknown `experiment run` option `{other}`; see \
                     `chronofork experiment --help`"
                ))
                .into());
            }
        }
        index += 1;
    }
    Ok(Some(options))
}

/// Parses a comma-separated list of decimal experiment checkpoints.
fn parse_checkpoints(value: &str, flag: &str) -> Result<Vec<u64>, CliError> {
    let mut checkpoints = Vec::new();
    for item in value.split(',') {
        let item = item.trim_matches([' ', '\t']);
        if item.is_empty() || !item.bytes().all(|byte| byte.is_ascii_digit()) {
            return Err(CliError(format!(
                "`{flag}` expects a comma-separated list of decimal integers, got `{value}`"
            )));
        }
        checkpoints.push(
            item.parse()
                .map_err(|_| CliError(format!("`{flag}` value `{item}` is too large")))?,
        );
    }
    Ok(checkpoints)
}

/// Writes bytes atomically: a temporary sibling file plus a rename in the same directory.
fn write_atomic(path: &Path, bytes: &[u8]) -> Result<(), Box<dyn Error>> {
    let file_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| {
            CliError(format!(
                "`--out` must name a file, got `{}`",
                path.display()
            ))
        })?;
    let parent = match path.parent() {
        Some(parent) if !parent.as_os_str().is_empty() => parent,
        _ => Path::new("."),
    };
    let temporary = parent.join(format!(".{file_name}.tmp-{}", std::process::id()));
    if let Err(error) = write_file(&temporary, bytes) {
        let _ = std::fs::remove_file(&temporary);
        return Err(CliError(format!("failed to write `{}`: {error}", path.display())).into());
    }
    if let Err(error) = std::fs::rename(&temporary, path) {
        let _ = std::fs::remove_file(&temporary);
        return Err(CliError(format!("failed to publish `{}`: {error}", path.display())).into());
    }
    Ok(())
}

fn write_file(path: &Path, bytes: &[u8]) -> io::Result<()> {
    let mut file = File::create(path)?;
    file.write_all(bytes)?;
    file.sync_all()
}

fn print_experiment_help() {
    println!("chronofork {VERSION} — experiment");
    println!();
    println!("Prints (or writes) the canonical `chronofork.experiment.v1` artifact");
    println!("document produced by the service `experiment.run` operation on the");
    println!("synthetic test backend. The document contains no host time, path or");
    println!("principal, so identical requests produce identical bytes.");
    println!();
    println!("Usage:");
    println!("  chronofork experiment run --steps <N> [--buttons <U32>]");
    println!("                            [--checkpoints <a,b,c>] [--out <FILE>]");
    println!();
    println!("Options:");
    println!("  --steps <N>          Required step budget, 1 or more");
    println!("  --buttons <U32>      Decimal input mask applied to every step (default 0)");
    println!("  --checkpoints <LIST> Comma-separated, strictly increasing steps in 0..=N");
    println!("  --out <FILE>         Atomically write the artifact bytes instead of printing");
    println!("  --help               Show this help");
    println!();
    println!("Output:");
    println!("  The canonical artifact document plus one newline on stdout, or exactly");
    println!("  those bytes in `--out`. `--artifacts` is a `serve` option, not this one.");
}
